{"concept":"A vibrant Diwali mela festival world glowing with deep marigold, saffron, and indigo night hues under strings of golden fairy lights.","fingerprint":"Cinzel Decorative, Saffron & Indigo, Gradient glow, Festooned gold","needsHud":false,"hudReason":"","id":"24aeb006305e","name":"Diwali Mela Festival","dark":true,"bg":"#0a0518","surface":"#1f0c38","surface2":"#2a1045","fg":"#ffe6cc","ink":"#ffe6cc","accent":"#ff9933","remapSurfaces":true,"customCss":"html, body{
 background-color: var(--m-bg) !important;
 color: var(--m-fg) !important;
 font-family: 'Poppins', sans-serif !important;
 background-image: radial-gradient(circle at 20% 20%, rgba(255,204,0,0.06) 0%, transparent 40%),
 radial-gradient(circle at 80% 80%, rgba(255,153,51,0.05) 0%, transparent 40%);
}[data-mydes="header"]{
 background: #1f0c38;
 border-bottom: 2px solid #ff9933;
 backdrop-filter: blur(10px);
 position: relative;
}[data-mydes="header"]::after{
 content: '';
 position: absolute;
 bottom: -2px; left: 0; right: 0;
 height: 2px;
 background: linear-gradient(90deg, transparent, #ffcc00, transparent);
 animation: headerGlow 3s ease-in-out infinite;
}
@keyframes headerGlow { 0%,100% { opacity:0.4; } 50% { opacity:1; } }[data-mydes="search"]{
 background: #0a0518;
 border: 1px solid #ffcc00;
 border-radius: 20px;
 color: #ffe6cc;
 transition: box-shadow 0.3s ease;
}
[data-mydes="search"]:focus-within {
 box-shadow: 0 0 12px rgba(255,204,0,0.6), inset 0 0 8px rgba(255,153,51,0.2);
}[data-mydes="chip"]{
 background: #2a1045;
 border: 1px solid #ff9933;
 border-radius: 12px;
 color: #ffcc00;
 text-transform: uppercase;
 letter-spacing: 0.8px;
 padding: 4px 12px;
 transition: background 0.2s, border-color 0.2s;
}[data-mydes="chip"]:hover{
 background: rgba(255,153,51,0.15);
 border-color: #ffcc00;
}[data-mydes="card"]{
 background: rgba(31,12,56,0.85);
 border-radius: 14px;
 border: 1px solid rgba(255,153,51,0.3);
 box-shadow: 0 0 20px rgba(255,204,0,0.25), inset 0 0 10px rgba(255,153,51,0.15);
 transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}[data-mydes="card"]:hover{
 transform: translateY(-3px);
 box-shadow: 0 0 25px rgba(255,153,51,0.6), inset 0 0 12px rgba(255,204,0,0.2);
 border-color: #ffcc00;
}
[data-mydes="heading"], [data-mydes="title"] {
 font-family: 'Cinzel Decorative', serif !important;
 text-transform: uppercase;
 letter-spacing: 1.2px;
 color: var(--m-ink) !important;
 text-shadow: 0 0 10px rgba(255,153,51,0.5);
}[data-mydes="btn"]:not(:has(svg, img)):not([aria-label]){
 background: linear-gradient(135deg, #ff9933 0%, #ffcc00 100%);
 border: none;
 border-radius: 8px;
 color: #0a0518;
 font-weight: 600;
 padding: 8px 16px;
 box-shadow: 0 4px 12px rgba(255,153,51,0.4);
 transition: box-shadow 0.2s, transform 0.2s;
}
[data-mydes="btn"]:hover {
 box-shadow: 0 6px 18px rgba(255,204,0,0.6);
 transform: translateY(-1px);
}[data-mydes="bottom-bar"]{
 background: #0a0518;
 border-top: 2px solid #ff9933;
 backdrop-filter: blur(10px);
 position: relative;
}[data-mydes="bottom-bar"]::before{
 content: '';
 position: absolute;
 top: -2px; left: 0; right: 0;
 height: 2px;
 background: linear-gradient(90deg, transparent, #ffcc00, transparent);
 animation: headerGlow 3s ease-in-out infinite;
}
a { color: var(--m-fg); text-decoration: none; }
/* review */
[data-mydes="card"] span, [data-mydes="card"], div[class*="modal"], div[style*="background"] { color: #ffe6cc !important; }","backdropHtml":"","hudHtml":"","customJs":""}

